/* ==========================================================================
   ACADEX · mürekkep & kâğıt arayüzü (js/acadex-ink.js)
   dashboard.js'ten SONRA yüklenir. dashboard.js'e dokunmaz: yalnızca
   Bugün / Belgelerim / Bölüm akışı / Bilgi kartları panellerinin çizim
   (render) fonksiyonlarını yeni tasarımla değiştirir. Veri sorguları,
   yükleme, özetleme, oylama, paylaşım, modallar aynen dashboard.js'te kalır.
   Demo veri yok: her şey Supabase'den gelen gerçek kayıtlardan çizilir;
   kayıt yoksa boş durum gösterilir.
   ========================================================================== */
/* ---------- isimler: her panelde aynı kural ----------
   1) Unicode NFC: Mac/iPhone'dan yazılan "Ş" bazen "S + ayrı çengel" olarak
      kaydediliyor; yazı tipi çengeli ayrı çizince isim eksik görünüyor.
   2) Profil yüklenmeden e-posta önekiyle ("suko.crc06") selamlamıyoruz;
      profil gelince isim yerine oturuyor.
   3) Tamamı büyük ya da küçük yazılmışsa Türkçe kurala göre baş harf büyük. */
window.axNm = function (s) { s = String(s == null ? '' : s); try { s = s.normalize('NFC'); } catch (e) {} return s.replace(/[​-‍﻿]/g, '').replace(/\s+/g, ' ').trim(); };
window.axCapWord = function (w) { w = window.axNm(w); if (!w) return ''; if (w === w.toLocaleLowerCase('tr') || w === w.toLocaleUpperCase('tr')) w = w.toLocaleLowerCase('tr'); return w.charAt(0).toLocaleUpperCase('tr') + w.slice(1); };
window.axFirstName = function (p, email) {
  var n = window.axNm(p && p.full_name);
  if (n) return window.axCapWord(n.split(' ')[0]);
  if (!email) return '';
  var w = String(email).split('@')[0].split(/[._\-+\d]+/).filter(function (x) { return x.length > 1; })[0] || '';
  return window.axCapWord(w);
};
window.axWhenProfile = function (cb) {
  var t0 = Date.now(), done = false;
  var get = function () { try { return currentUserProfile; } catch (e) { return window.currentUserProfile || null; } };
  var tick = function () {
    if (done) return; var p = get();
    if (p && p.full_name !== undefined) { done = true; if (p.full_name) p.full_name = window.axNm(p.full_name); cb(p); return; }
    if (Date.now() - t0 > 15000) { done = true; cb(null); return; }
    setTimeout(tick, 250);
  };
  tick();
};
/* BILDIRIM GOSTER (25.10.2026, test raporu R7). Android Chrome'da sayfadan
   new Notification() "Illegal constructor" atar; hata sessizce yutuldugu icin
   telefonda hic bildirim gelmiyordu. Once servis calisani (sw.js) uzerinden
   gosterilir, olmazsa eski yola duser. Sonuc: true/false. */
window.axNotify = function (title, opts) {
  opts = opts || {};
  if (!('Notification' in window) || Notification.permission !== 'granted') return Promise.resolve(false);
  var plain = function () { try { new Notification(title, opts); return true; } catch (e) { return false; } };
  if (!('serviceWorker' in navigator)) return Promise.resolve(plain());
  var reg = window.__axSwReg || (window.__axSwReg = navigator.serviceWorker.register('sw.js').then(function () { return navigator.serviceWorker.ready; }));
  var timeout = new Promise(function (r) { setTimeout(function () { r(null); }, 4000); });
  return Promise.race([reg, timeout]).then(function (r) {
    if (r && r.showNotification) return r.showNotification(title, opts).then(function () { return true; }, function () { return plain(); });
    return plain();
  }, function () { return plain(); });
};
