      var meta = (rSel === 'all' ? esc(c.desk.name) + ' · ' : '') + 'son ' + c.recentExams + ' denemede ort. ' + c.recentAvg + ' · ' + when + ' · ' + c.n + ' soru · hafıza %' + c.retention + (c.fewData ? ' · az veri' : '');
